def max_product(num_str, N, K):
    nums = [int(x) for x in num_str]
    dp = [[0] * (N + 1) for _ in range(N + 1)]

    for i in range(N):
        dp[i][i] = nums[i]
        for j in range(i + 1, N):
            dp[i][j] = max(dp[i][j - 1] * nums[j], nums[j])

    for _ in range(K):
        for i in range(N):
            for j in range(i + 1, N):
                dp[i][j] = max(dp[i][j], dp[i][k] * dp[k + 1][j] for k in range(i, j))

    return max(dp[0][N - 1])
```
