def optimize_seating(M, N, K, L, D, chatting_pairs):
    # Initialize a matrix to store the number of chatting pairs that can be separated by adding an aisle in each position
    separation_matrix = [[0] * N for _ in range(M)]

    # Iterate over each chatting pair and check if an aisle can be placed on either side of the pair
    for x1, y1, x2, y2 in chatting_pairs:
        for i in range(x1-1, x2+2):
            for j in range(y1-1, y2+2):
                if (i, j) not in chatting_pairs and (i, j) not in [(x1, y1), (x2, y2)]:
                    separation_matrix[i][j] += 1

    # Find the maximimum number of chatting pairs that can be separated
    max_separation = max(max(row) for row in separation_matrix)

    # Find the row and column indices of the maximum separation
    max_row, max_col = 0, 0
    for i in range(M):
        for j in range(N):
            if separation_matrix[i][j] == max_separation:
                max_row, max_col = i, j
                break

    # Convert the row and column indices to a list of strings
    row_indices = [str(i) for i in range(max_row, max_row + K)]
    col_indices = [str(i) for i in range(max_col, max_col + L)]

    return " ".join(row_indices), " ".join(col_indices)
