def max_happiness(n: int, m: int, items: List[Tuple[int, int]]) -> int:
    # Initialize a list to store the results of the recursive calls
    results = [0] * (m + 1)

    # Base case: if the budget is 0 or there are no more items to consider, return 0
    if n == 0 or m == 0:
        return 0

    # If the current item price is less than or equal to the budget, recursively call the function with the remaining budget and the remaining number of items
    if items[m - 1][0] <= n:
        results[m] = max(results[m - 1], results[m - 1] + items[m - 1][1])

    # If the current item price is greater than the budget, recursively call the function with the remaining budget and the remaining number of items
    else:
        results[m] = results[m - 1]

    # Return the maximum total importance value that can be achieved without exceeding the budget
    return max(results)
