def is_prime(num: int) -> bool:
    # Handles edge cases
    if num <= 1:
        return False
    if num <= 3:
        return True

    # Checks for divisibility by 2 and 3
    if num % 2 == 0 or num % 3 == 0:
        return False

    # Uses the 6k +/- 1 optimization for larger numbers
    i = 5
    while i * i <= num:
        if num % i == 0 or num % (i + 2) == 0:
            return False
        i += 6

    return True
