def max_herb_value(T: int, M: int, herbs: List[Tuple[int, int]]) -> int:
    # Initialize the dp array with 0 for all rows and columns
    dp = [[0] * (M + 1) for _ in range(T + 1)]

    # Loop through each time step
    for t in range(1, T + 1):
        # Loop through each herb
        for i in range(1, M + 1):
            # Check if the current herb's time cost is less than or equal to the current time step
            if t >= herbs[i - 1][0]:
                # Update the dp value with the maximum of the current value and the previous value plus the current herb's value
                dp[t][i] = max(dp[t - herbs[i - 1][0]][i - 1] + herbs[i - 1][1], dp[t][i - 1])
            else:
                # If the current herb's time cost is greater than the current time step, set the dp value to the previous value
                dp[t][i] = dp[t][i - 1]

    # Return the maximum value in the last row of the dp array
    return max(dp[T])
```

